package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamLowCountryMasksBank1 {
    private const val T = "පහතරට නර්තන සම්ප්‍රදාය හා වෙස්මුහුණු කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පහතරට නර්තන සම්ප්‍රදායේ ප්‍රධානතම බෙරය කුමක්ද?", "යක් බෙරය (රුහුණු බෙරය)", "ගැටබෙරය", "දිගු දවුල", "තම්මැට්ටම", "පහතරට දෙවොල් මඩු හා සන්නි යකුම් සඳහා වයන ප්‍රධාන බෙරය යක් බෙරයයි."),
        q("පහතරට නර්තන සම්ප්‍රදාය ප්‍රධාන වශයෙන් බෙදී ඇති ප්‍රාදේශීය ගුරුකුල තුන මොනවාද?", "මාතර, බෙන්තර සහ රයිගම", "මහනුවර, මාතලේ සහ කෑගල්ල", "රත්නපුර, බලංගොඩ සහ ඇඹිලිපිටිය", "යාපනය, මන්නාරම සහ වවුනියාව", "දකුණු හා බස්නාහිර පළාත් ආශ්‍රිතව මෙම පහතරට ගුරුකුල තුන ප්‍රචලිත විය."),
        q("පහතරට නැට්ටුවාගේ ප්‍රධාන සම්ප්‍රදායික හිස් වැසුම ලෙස සැලකෙන රතු පැහැති තොප්පිය කුමක්ද?", "තෙල්මේ තොප්පිය හෙවත් මුදුන් තොප්පිය", "උඩරට වෙස් තට්ටුව", "කෝලම් ඔටුන්න", "සබරගමු තලප්පාව", "උස් වූ රතු හා රන් පැහැති සැරසිලි සහිත තෙල්මේ තොප්පිය පහතරට අනන්‍යතාවයකි."),
        q("පහතරට නර්තන සම්ප්‍රදායේදී ශිල්පියාගේ කයට පළඳින දිගු රැළි සහිත සුදු හා රතු වස්ත්‍රය කුමක්ද?", "තෙල්මේ ඇඳුමේ කබාය හා හඟල", "උඩරට වෙස් අවුල්හැරය", "නෛයන්ඩි සුදු ජටාව", "සොකරි කමත් ඇඳුම", "පහතරට තෙල්මේ නැට්ටුවා උඩුකයට කබායක් හෝ පබළු මාල හා පහළට රැළි හඟල අඳියි."),
        q("පහතරට සම්ප්‍රදායේ ප්‍රධාන සමූහ දේව ආශිර්වාද නැටුම් අංගය කුමක්ද?", "තෙල්මේ නැටුම", "වෙස් නැටුම", "කළගෙඩි නැටුම", "ලී කෙළි නැටුම", "දෙවොල් මඩු හා ගම්මඩු වලදී ඉදිරිපත් කරන තෙල්මේ නැටුම පහතරට නැටුමේ පදනමයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේදී ආධුනික ශිල්පියෙකු පුහුණු වන මූලික සරඹ මාලාව කුමක්ද?", "තෙල්මේ සරඹ හා මූලික ගොඩ සරඹ 12", "කොහොඹා කංකාරි සරඹ", "භරත අඩව් සරඹ", "කථක් චක්කර් සරඹ", "පහතරට නැටුමේදී දෙපා පළල් කර තෙල්මේ ඉරියව්වෙන් සරඹ පුහුණු කෙරේ."),
        q("පහතරට වෙස්මුහුණු කලාව ප්‍රධාන වශයෙන් කැපීමට යොදාගන්නා සැහැල්ලු ශාක දැවය කුමක්ද?", "වෙල් කදුරු (රුක් අත්තන) දැවය", "කළුවර දැවය", "තේක්ක දැවය", "කොස් දැවය", "කැටයම් කිරීමට පහසු හා බරින් ඉතා අඩු වෙල් කදුරු ලීය වෙස්මුහුණු සෑදීමට යොදයි."),
        q("ශ්‍රී ලංකාවේ පාරම්පරික වෙස්මුහුණු කලාවේ ප්‍රධාන මධ්‍යස්ථානය ලෙස ප්‍රකට නගරය කුමක්ද?", "අම්බලන්ගොඩ", "මහනුවර", "අනුරාධපුරය", "බදුල්ල", "අම්බලන්ගොඩ ප්‍රදේශය කෝලම් හා සන්නි වෙස්මුහුණු කැපීම සඳහා ලෝක ප්‍රසිද්ධය."),
        q("පහතරට වෙස්මුහුණු කලාව ප්‍රධාන වශයෙන් අයත් වන කලා අංග තුන මොනවාද?", "කෝලම්, සන්නි සහ රක්ෂ (රකුසු) මුහුණු", "වෙස්, නෛයන්ඩි සහ උඩැක්කි", "රබන්, කළගෙඩි සහ කුලු", "වන්නම්, සරඹ සහ අඩව්", "නාට්‍යමය කෝලම් මුහුණු, ශාන්තිකර්ම සන්නි මුහුණු හා අලංකාර රකුසු මුහුණු මෙයට අයත් වේ."),
        q("පහතරට 'දහඅට සන්නිය' ශාන්තිකර්මයේදී නිරූපණය කෙරෙන සන්නි යකුන් සංඛ්‍යාව කීයද?", "දහඅටකි (18)", "දොළහකි (12)", "විසිහතරකි (24)", "හතළිස් දෙකකි (42)", "විවිධ රෝගාබාධ සංකේතවත් කරන සන්නි යකුන් 18 දෙනාගේ පුවත මෙහි රඟ දැක්වේ."),
        q("දහඅට සන්නියේ සියලු සන්නි යකුන්ගේ නායකයා ලෙස පැමිණෙන ප්‍රධාන වෙස්මුහුණු චරිතය කුමක්ද?", "මහ කෝල සන්නි යකා", "ජසයා", "ලෙන්චිනා", "පරයා", "සන්නි යකුන් දහඅට දෙනාගේම රූප කැටයම් කළ විශාල මුහුණක් මහ කෝල සන්නියට ඇත."),
        q("දහඅට සන්නියේදී කන් නොඇසීමේ රෝගය සංකේතවත් කරමින් වෙස්මුහුණ පැළඳ පැමිණෙන සන්නිය කුමක්ද?", "බිහිරි සන්නිය", "කණ සන්නිය", "කොර සන්නිය", "ගොළු සන්නිය", "බිහිරි පුද්ගලයෙකුගේ හැසිරීම හාස්‍යජනක දෙබස් මඟින් බිහිරි සන්නියේදී රඟ දැක්වේ."),
        q("දෑස් නොපෙනීමේ හෙවත් අන්ධභාවයේ රෝගය පෙන්වන සන්නි වෙස්මුහුණ කුමක්ද?", "කණ සන්නිය", "මරු සන්නිය", "ගිනිජල් සන්නිය", "දෙමළ සන්නිය", "ඇස් පෙනීම දුර්වල හෝ නැති පුද්ගලයෙකුගේ ඉරියව් කණ සන්නිය මගින් දැක්වේ."),
        q("කථන ආබාධයක් හෙවත් කතා කිරීමට නොහැකි රෝග තත්ත්වය නිරූපණය කරන සන්නිය කුමක්ද?", "ගොළු සන්නිය", "බිහිරි සන්නිය", "වාත සන්නිය", "පිත් සන්නිය", "වචන නොපැහැදිලිව හෝ අභිනයෙන් අදහස් පවසමින් ගොළු සන්නිය රඟපායි."),
        q("පාදවල ආබාධයක් හෙවත් කොර ගසමින් ඇවිදින රෝගය නිරූපණය කරන සන්නිය කුමක්ද?", "කොර සන්නිය", "නාග සන්නිය", "වැදි සන්නිය", "කුලප්පු සන්නිය", "සැරයටියක් අතැතිව හෝ කොර ගසමින් වේදිකාවට පැමිණීම කොර සන්නියේ සිරිතයි."),
        q("අධික උණ, දාහය හා උෂ්ණ රෝග සංකේතවත් කරමින් රතු පැහැ වෙස්මුහුණෙන් පැමිණෙන සන්නිය කුමක්ද?", "ගිනිජල් සන්නිය", "සීතල සන්නිය", "බිහිරි සන්නිය", "කණ සන්නිය", "උණ ගැනීමෙන් ඇති වන දැවිල්ල හා උණ විකාරය ගිනිජල් සන්නියෙන් නිරූපණය වේ."),
        q("මරණාසන්න බිය හා අපස්මාරය වැනි දරුණු රෝගාබාධ සංකේතවත් කරන සන්නි යකා කවුද?", "මරු සන්නිය", "ගොළු සන්නිය", "කොර සන්නිය", "මුරුත සන්නිය", "වියරු වැටුණු ස්වරූපයක් ගත් මරු සන්නිය වෙස්මුහුණ විශාල දළ සහිතව නිමවා ඇත."),
        q("වමනය හා උදරාබාධ වැනි රෝග සමනය කිරීමට නටන සන්නි අංගය කුමක්ද?", "වමන සන්නිය හෙවත් අභූත සන්නිය", "දේව සන්නිය", "නාග සන්නිය", "වැදි සන්නිය", "ආහාර අජීර්ණ හා උදර රෝග වෙනුවෙන් පහතරට සන්නි අතර මෙය රඟ දැක්වේ."),
        q("පහතරට 'කෝලම්' ගැමි නාට්‍යයේ ආරම්භයේදීම සභාව හඳුන්වා දී කතාව මෙහෙයවන චරිතය කවුද?", "සභාපති හෙවත් කාරියකරවන රාළ", "මහ කෝල සන්නියා", "මලය රජු", "ගුරුහාමි", "සභාපති විසින් කවි ගයා සෑම කෝලම් චරිතයක්ම ප්‍රේක්ෂකයාට හඳුන්වා දෙයි."),
        q("කෝලම් නාට්‍යයේ හාස්‍ය රසය උපදවන ප්‍රධාන ස්වාමි-භාර්යා යුගලය කවුද?", "ජසයා සහ ලෙන්චිනා", "ගුරුහාමි සහ සොකරි", "සාලිය සහ අශෝකමාලා", "මනමේ කුමරු සහ කුමරිය", "මහලු රෙදි අපුල්ලන ජසයා සහ තරුණ ලෙන්චිනාගේ විවාහ ජීවිතය කෝලමේ රසවත් අංගයකි."),
        q("කෝලම් නාට්‍යයේ ප්‍රධාන රාජකීය චරිතය හඳුන්වන්නේ කුමන නමකින්ද?", "මහ සම්මත රජු හෝ සිංහ රාජ කෝලම", "පරයා", "වැදි නායකයා", "නොංචි අක්කා", "ගර්භණී රජ බිසවගේ දොළදුක සංසිඳුවීමට කෝලම් නැටූ බව ජනප්‍රවාදයේ සඳහන් වේ."),
        q("කෝලම් නැටුමේදී යුද සෙබළුන්ගේ චරිත ලෙස මුහුණු පැළඳ පැමිණෙන විකට චරිත හඳුන්වන්නේ කෙසේද?", "හේවා රාළලා හෙවත් හේවා කෝලම", "පත්තිනි හාමි", "දෙවොල් දෙවියෝ", "වඩිග බමුණෝ", "කඩු පලිහ ගෙන විකට ආකාරයෙන් ගමන් කරන හේවා කෝලම් චරිත සමාජ උපහාසය පෙන්වයි."),
        q("පහතරට 'කෝලම්' නැටුමේදී මහලු කාන්තා චරිතයක් නිරූපණය කරමින් හාස්‍ය මවන චරිතය කවුද?", "නොංචි අක්කා", "සොකරි අම්මා", "කුවේණිය", "මායා දේවි", "මහලු කාන්තාවකගේ ගමන් හා විකට කතා බහ නොංචි කෝලමෙන් නිරූපණය කෙරේ."),
        q("පහතරට 'කෝලම්' කතා පෙළ අවසානයේ රඟ දක්වන ප්‍රධාන දේව හා සත්ව පෙළපාලි චරිත මොනවාද?", "නාග රක්ෂ, ගුරුළු රක්ෂ සහ මරුවා", "තුරඟා සහ මුසලඩි", "ලී කෙළි සහ කළගෙඩි", "මලය රජු සහ කිත්සිරි", "නාග රක්ෂ හා ගුරුළු රක්ෂ සටන් රංගනය කෝලම් කලාවේ ඉහළම කලා අංගයකි."),
        q("ගුරුළු රක්ෂ වෙස්මුහුණ නිර්මාණය කර ඇත්තේ කුමන ආකාරයේ සංකේත එකතුවකින්ද?", "නාගයෙකු මුවින් ඩැහැගත් පක්ෂි රාජයෙකුගේ ස්වරූපයෙන්", "ඇත් හිසක් හා මිනිස් සිරුරකින්", "සිංහ මුහුණකින් පමණි", "සාමාන්‍ය මිනිස් මුහුණකින්", "ගුරුළා හා නාගයා අතර පවතින පාරම්පරික වෛරය මෙම වෙස්මුහුණෙන් දැක්වේ."),
        q("නාග රක්ෂ වෙස්මුහුණ හඳුනාගත හැකි ප්‍රධානතම දෘශ්‍ය ලක්ෂණය කුමක්ද?", "මුහුණ වටා නාග පෙන කිහිපයක් විහිදී තිබීම", "හිස මත ඇත් දළ දෙකක් තිබීම", "මුහුණේ කිසිදු වර්ණයක් නොතිබීම", "පිදුරු රැවුලක් තිබීම", "නාග කන් හා නාග පෙන රාශියක් කැටයම් කර ඇති අලංකාර වෙස්මුහුණකි."),
        q("පහතරට 'මයුර රක්ෂ' වෙස්මුහුණේ හිස මත කැටයම් කර ඇති පක්ෂියා කවුද?", "මොනරා", "උකුස්සා", "කපුටා", "ගිරවා", "සෞභාග්‍යය හා රෝග නිවාරණ ආශිර්වාදය සංකේතවත් කරමින් මයුර රක්ෂ මුහුණ සාදා ඇත."),
        q("පහතරට වෙස්මුහුණු පින්තාරු කිරීමේදී පැරණි ශිල්පීන් භාවිත කළ ස්වාභාවික වර්ණකයක් කුමක්ද?", "මකුළු මැටි, සාදිලිංගම් සහ දොරණ තෙල් මිශ්‍රණ", "කෘත්‍රිම එනැමල් හා ලැකර් තීන්ත", "ජල ද්‍රාව්‍ය පෝස්ටර් සායම් පමණි", "ලෝහ ආලේපන හා වාර්නිෂ් තීන්ත", "දේශීය ඛනිජ හා ශාක වර්ණක මත දොරණ තෙල් ගෑමෙන් දීප්තිමත් බව හා ආරක්ෂාව ලැබිණි."),
        q("වෙස්මුහුණු කැපීමේදී ඒවායේ ඇස් සිදුරු හා මුඛ සිදුරු තබන්නේ කුමන ප්‍රායෝගික හේතුව නිසාද?", "නැට්ටුවාට පිටත පෙනීමට, හුස්ම ගැනීමට හා කතා කිරීමට", "වෙස්මුහුණේ බර වැඩි කිරීමට", "ලීය ඉක්මනින් දිරාපත් වීමට", "වර්ණ නොගෑමට", "වෙස්මුහුණ පැළඳ සිටියදී ආරක්ෂිතව වේදිකාව දැකීමට හා හුස්ම ගැනීමට සිදුරු අත්‍යවශ්‍ය වේ."),
        q("පහතරට නර්තන සම්ප්‍රදායේදී භාවිත කරන 'සළු පාලිය' යනු කුමක්ද?", "පත්තිනි දේවියගේ සළුව පෙන්වමින් කරන පූජාමය නැටුම් පෙළපාලියක්", "උඩරට කංකාරියේ කඩු හරඹ පෙන්වන පූජාමය නැටුම් පෙළපාලියක්", "සබරගමු පහන් මඩුවේ කළගෙඩි රැගෙන නටන ගැමි ජන නැටුමක්", "කෝලම් රඟමඬලේ සෙබළ වෙස්මුහුණු පැළඳ ඉදිරිපත් කරන විකට අංගයක්", "සුදු සළුවක් අතැතිව පාලි නැටුමෙන් රෝගීන්ට ආශිර්වාද කිරීම සළු පාලියෙන් සිදු වේ."),
        q("පහතරට නර්තනයේ 'දෙවොල් මඩුව' ශාන්තිකර්මයේදී නැට්ටුවා උඩුකයට පළඳින වස්ත්‍රය කුමක්ද?", "තෙල්මේ හැට්ටය හෝ පබළු මාල සහිත උරමාලය", "උඩරට රිදී අවුල්හැරය", "බටහිර ජැකට්ටුව", "කිසිදු වස්ත්‍රයක් නොමැත", "රතු හා සුදු වර්ණ ප්‍රමුඛ කොට ගත් පහතරට සම්ප්‍රදායික ඇඳුම භාවිත වේ."),
        q("පහතරට නර්තන කලාවේ 'මණ්ඩිය' උඩරට මණ්ඩියෙන් වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "උඩරටට වඩා තරමක් විවෘත හා ඉදිරියට නැඹුරු වූ පුළුල් ඉරියව්ව", "දණහිස් කිසිසේත්ම නොනැමීම", "එක් කකුලක් පමණක් භාවිත කිරීම", "බිම දිගා වී සිටීම", "පහතරට මණ්ඩියේ පාද තැබීමේ රිද්මය හා පපුව ඉදිරියට ගැනීම ආවේණික වේ."),
        q("පහතරට නැටුමේදී යක් බෙරය වාදනය කරන අතරතුර 'යක් බෙර පද' කියවන ප්‍රධාන මූලික අක්ෂර මොනවාද?", "දොං, ජිං, තක, තරි, කිට", "ස, රි, ග, ම", "ඩෝ, රේ, මී, ෆා", "ඒ, බී, සී, ඩී", "පහතරට යක් බෙරයේ මූලික නාද උපදින බීජාක්ෂර මේවා වේ."),
        q("පහතරට 'පහන් පාලිය' හෝ 'පන්දම් පාලිය' තුළින් නිරූපණය කෙරෙන සංකේතාත්මක අර්ථය කුමක්ද?", "අන්ධකාරය හා අමනුෂ්‍ය දෝෂ දුරු කර ආලෝකය ලබාදීම", "ශාලාවේ වාතාශ්‍රය අඩු කිරීම", "වේදිකාවට ගිනි තැබීම", "නැටුම අවසන් කිරීම", "දැල්වෙන පන්දම් ගෙන කරන නැටුම් පාලි මඟින් පාරිශුද්ධත්වය ඇති කෙරේ."),
        q("පහතරට 'දහඅට සන්නිය' අවසානයේදී යකැදුරා රෝගියාට ආශිර්වාද කරන්නේ කුමන පූජා ද්‍රව්‍යයක් භාවිතයෙන්ද?", "පඬුරු, පිරිත් නූල් සහ දුම්මල", "සීතල අයිස් කැට", "ලෝහ දම්වැල්", "කඩදාසි මල්", "යාගය අවසානයේ සෙත් පිරිත් හා ආශිර්වාද කවි මගින් රෝගියාගේ මානසික ශක්තිය වඩවයි."),
        q("පහතරට 'වඩිග පටුන' නමැති විශේෂිත නැටුම් හා නාට්‍ය අංගය ඉදිරිපත් කරන්නේ කුමන ශාන්තිකර්මයකදීද?", "සූනියම් කැපිල්ල හෙවත් ශූනියම් යාගයේදී", "කොහොඹා කංකාරියේදී", "සොකරි නාටකයේදී", "මහනුවර පෙරහැරේදී", "වඩිග රටින් පැමිණි බමුණන් හත්දෙනාගේ කතා පුවත සූනියම් යාගයේ රඟ දැක්වේ."),
        q("වඩිග පටුන රංගනයේදී බමුණන් පැළඳ සිටින විශේෂිත ඇඳුම් අංග මොනවාද?", "උල් තොප්පි, දිගු සුදු රැවුල් සහ සුදු පූන නූල්", "උඩරට වෙස් තට්ටු", "සන්නි යක් මුහුණු", "රතු තෙල්මේ ඇඳුම්", "හාස්‍ය හා පුරාවෘත්ත ගුණය එක් කරමින් බමුණු වෙස් ගෙන මෙය රඟ දැක්වේ."),
        q("පහතරට නර්තනයේ 'කළස පාලිය' මගින් දැක්වෙන්නේ කුමන ශුභ සංකේතයද?", "පූර්ණ කළස හෙවත් සශ්‍රීකත්වය හා සෞභාග්‍යය", "සාගතය හා නියඟය", "යුද්ධය හා විනාශය", "රෝග බිය", "ජලය හා පොල් මලක් තැබූ පුන් කළසක් ගෙන නැටීම ශුභ නිමිත්තකි."),
        q("පහතරට කෝලම් නාට්‍යයේ 'මුදලි කෝලම' මගින් විවේචනයට හෝ උපහාසයට ලක් කෙරෙන සමාජ චරිතය කවුද?", "යටත් විජිත සමයේ අහංකාර රජයේ නිලධාරීන් හා ගම් මුලාදෑනීන්", "ගොවි ජනතාව", "වෙහෙර විහාර භික්ෂූන් වහන්සේලා", "පාසල් දරුවන්", "ලන්දේසි හා ඉංග්‍රීසි යුගවල පැවති පරිපාලන නිලධාරීන් කෝලමෙන් උපහාසයට ලක් විය."),
        q("කෝලම් කලාවේදී 'මාර කෝලම' හෝ 'මරුවා' චරිතයේ වෙස්මුහුණ වර්ණ ගන්වන්නේ කුමන ප්‍රධාන වර්ණයෙන්ද?", "තද රතු සහ කළු වර්ණවලින්", "ලා සුදු පැහැයෙන් පමණි", "රෝස පැහැයෙන් පමණි", "නිල් පැහැයෙන් පමණි", "බියකරු බව හා රෞද්‍ර බව පෙන්වීම සඳහා රතු, කළු හා නෙරා ගිය දත් යොදයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේදී 'තෙල්මේ' නැටුම අවසන් කිරීමේදී යොදාගන්නා අවසන් නර්තන රටාව කුමක්ද?", "අඩව් කස්තිරම් සහ හමාර තීර්මානය", "ගොයම් කැපීම", "කළගෙඩි කරකැවීම", "බංකු රබන් ගැසීම", "සෑම පහතරට සමූහ නැටුමක්ම වේගවත් හමාර තීර්මානයකින් අවසන් වේ."),
        q("පහතරට 'මහ සොහොන් සමයම' නමැති යාතුකර්මයේදී නැට්ටුවා කවර වෙසක් ගනීද?", "වලස් මුහුණක් සහිත මහ සොහොන් යක්ෂයාගේ ස්වරූපය", "මොනර රජුගේ ස්වරූපය", "හංසයාගේ ස්වරූපය", "වැදි රජුගේ ස්වරූපය", "දරුණු රෝග හා බිය දුරු කිරීම සඳහා මහ සොහොන් සමයම රාත්‍රියේ පවත්වනු ලැබේ."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'පූර්ණක' හෝ 'කැළෑ රක්ෂ' මුහුණුවල විශේෂ ලක්ෂණය කුමක්ද?", "ගිනි සිළු වැනි රවුම් ඇස් හා නාග පෙන කැටයම්", "සම්පූර්ණ සමතල මතුපිට", "කිසිදු කැටයමක් නොමැති වීම", "කුඩා මල් පෙති පමණක් තිබීම", "දේශීය වෙස්මුහුණු කැටයම්කරුගේ නිර්මාණශීලීත්වය මෙම මුහුණුවලින් ප්‍රකට වේ."),
        q("පහතරට නැටුමේදී 'පහතරට යක් බෙරය' කරේ එල්ලා වාදනය කරන්නේ ඇයි?", "නැටුමට අනුව ඇවිදිමින් පහසුවෙන් වැයීමට", "බෙරය පොළොව මත තැබීම අපහසු වීම නිසා", "යක් බෙරය ඉතා කුඩා ප්‍රමාණයේ නිසා", "කඩිප්පු යුගලයකින් තදින් ගැසීම සඳහා", "රෙදි වරපටියකින් ඉණ මට්ටමේ එල්ලාගෙන දෙඅතින් යක් බෙරය වයයි."),
        q("පහතරට සන්නි වෙස්මුහුණු අතරින් මුඛය පැත්තකට ඇද වී ඇති ආකාරයට කපන වෙස්මුහුණ කුමක්ද?", "වාත සන්නිය හෙවත් කෝල සන්නිය", "සීතල සන්නිය", "දේව සන්නිය", "රන් සන්නිය", "අංශභාග හා වාත රෝග ලක්ෂණ කලාත්මකව එම මුහුණේ නිරූපණය කර ඇත."),
        q("පහතරට නර්තන ක්ෂේත්‍රයේ 'ගුරුකුල' අතරින් පුරාණ ශාන්තිකර්ම පෙළපාලි වඩාත් දිගු ආකාරයෙන් රැකී ඇත්තේ කුමන ගුරුකුලයේද?", "මාතර සහ බෙන්තර ගුරුකුලවල", "මහනුවර ගුරුකුලයේ", "මන්නාරම ගුරුකුලයේ", "නුවරඑළිය ගුරුකුලයේ", "දකුණු ලක පැරණි යකැදුරු පරම්පරා මෙම සම්ප්‍රදායන් රැකගත්හ."),
        q("පහතරට නැටුමේදී 'නටන පිටිය' හෙවත් රංග භූමිය හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "යාග මඩුව හෙවත් තොරණ ඉදිරි මළුව", "දණ්ඩියම් කුටිය", "කවිකාර මඩුව", "මල් වත්ත", "කෙසෙල් කඳන් හා ගොක් කොළවලින් සරසන ලද යාග මඩුව පහතරට රඟමඬලයි."),
        q("කෝලම් නැටුමේ 'පනික්කල' හෝ 'පෙදෙරේරු' වැනි චරිත ඇතුළත් කිරීමෙන් පැරැන්නන් අපේක්ෂා කළේ කුමක්ද?", "විවිධ වෘත්තිකයන් හා සමාජය උපහාසයට නැඟීම", "පහතරට ශාන්තිකර්ම මන්ත්‍ර සජ්ඣායනය කිරීම", "උඩරට වන්නම් කවි තාලයට ගායනා කිරීම", "දේව යාග සඳහා මල් යහන් තනා සැරසීම", "ගැමි ජනතාවගේ සමාජ දැනුම හා විනෝදාස්වාදය සඳහා කෝලම් භාවිත විය."),
        q("පහතරට 'රට යකුම' හෙවත් 'රිද්දි යාගය' පැවැත්වීමේදී ප්‍රධාන වශයෙන් ඉදිරිපත් කරන නර්තන අංගයක් කුමක්ද?", "දොළහ පාලිය සහ රිද්දි බිසවුන්ගේ කතා පුවත", "වන්නම් දහඅට", "සොකරි හා පරයා නැටුම", "කළගෙඩි නැටුම", "දරුවෙකු ලැබෙන්නට සිටින මවට ආශිර්වාද කිරීම මෙම යාගයේ අරමුණයි."),
        q("පහතරට නර්තන ඇඳුමේදී පාදවල පළඳිනු ලබන ශබ්ද උපදවන පළඳනාව කුමක්ද?", "සිළම්බු හෙවත් පා සළඹ", "අවුල්හැරය", "ජටා පටිය", "පන්තේරුව", "උඩරට මෙන්ම පහතරට නර්තනයේදීද තාලයට නාද දීමට සිළම්බු පළඳියි."),
        q("පහතරට 'දහඅට සන්නිය' ශාන්තිකර්මයේදී 'කපු සන්නිය' හෙවත් 'භූත සන්නිය' පැමිණි විට පෙන්වන රෝග ලක්ෂණ කුමක්ද?", "සෙම් හා භූත දෝෂ නිසා ඇති වන ඇඟ වෙව්ලීම හා අපහසුතා", "කන් නොඇසීම පමණක්", "කොර ගැසීම පමණක්", "ඇස් නොපෙනීම පමණක්", "එක් එක් සන්නිය මිනිස් සිරුරේ විශේෂ රෝග තත්ත්වයක් නිරූපණය කරයි."),
        q("පහතරට සන්නි වෙස්මුහුණු අතරින් 'දෙමළ සන්නිය' හඳුනා ගත හැකි මුහුණු ලක්ෂණය කුමක්ද?", "නළලේ තිලකය හා දකුණු ඉන්දීය ආභාසය පෙන්වන සැරසිලි", "නාග පෙන දහඅටක් තිබීම", "ඇත් හොඬවැලක් තිබීම", "වලස් මුහුණක් තිබීම", "විවිධ සංස්කෘතික චරිත සන්නි අතර හාස්‍යයෙන් නිරූපණය කෙරේ."),
        q("පහතරට 'මහ සන්නි' වෙස්මුහුණේ මුදුනේම බොහෝ විට කැටයම් කර ඇති රූප සංකේතය කුමක්ද?", "නාග පෙන සහ යක්ෂ ඔටුන්න", "සූර්ය පිරෙයි", "මොනර පිල්", "පිදුරු තොප්පිය", "සන්නි යකුන්ගේ ප්‍රධානියාගේ බලපරාක්‍රමය මෙම ඔටුන්නෙන් ප්‍රකට කෙරේ."),
        q("පහතරට 'සීතල සන්නිය' මඟින් රෝගියා තුළ සමනය කිරීමට අපේක්ෂා කරන රෝග තත්ත්වය කුමක්ද?", "අධික ශීතල, ගැහීම සහ සෙම්ප්‍රතිශ්‍යා උණ තත්ත්වය", "අධික පිපාසය හා දාහය", "කන් කැක්කුම", "ඇස් රතු වීම", "සිරුරේ වා පිත් සෙම් අසමතුලිතතා සන්නි නාමවලින් හඳුනා ගෙන ඇත."),
        q("පහතරට 'ගුල්ම සන්නිය' මඟින් නිරූපණය කරන රෝගී ස්වභාවය කුමක්ද?", "උදරයේ ගෙඩි හෝ ආමාශගත වේදනා සහ අජීර්ණ රෝග", "හිසරදය පමණි", "දත් කැක්කුම පමණි", "කකුල් කැඩීම", "පැරණි ආයුර්වේද දැනුම හා යාග කලාව සන්නි නාමකරණයේදී එකට බැඳී ඇත."),
        q("පහතරට 'කෝලම්' නාට්‍යයේ ප්‍රධාන පිටපත හෝ සංවාද පරම්පරාගතව රැකගෙන ආ මාධ්‍යය කුමක්ද?", "කෝලම් කවි පුස්කොළ පොත් හා මුඛ පරම්පරාගත ගායනා", "සමකාලීන නූතන නවකතා හා කෙටිකතා පොත්", "බටහිර සම්භාව්‍ය ඔපෙරා ගීත සංග්‍රහ පොත්", "පැරණි සෙල්ලිපි හා ටැම් ලිපි කැටයම්", "පරම්පරාගත ගුරු පොත් මගින් පහතරට කෝලම් කවි අද දක්වා සුරැකිණි."),
        q("පහතරට 'කෝලම්' නාට්‍යයේ 'හේවා කෝලම' වේදිකාවට පිවිසෙන විට ඔවුන්ගේ මුහුණුවල දැකිය හැකි විශේෂ විකට ලක්ෂණය කුමක්ද?", "තුවාල වූ නාසය, කැපුම් කැළැල් සහ උඩු රැවුල", "මල් මාලා හා ඔටුනු", "සුදු පැහැති සිනිඳු මුහුණ", "නාග පෙන", "යුද්ධයෙන් ආපසු ආ විකට සෙබළුන්ගේ පෙනුම හාස්‍ය රසය උපදවයි."),
        q("කෝලම් නාට්‍යයේ 'ලෙන්චිනා' චරිතය පිළිබඳ නිවැරදි හැඳින්වීම කුමක්ද?", "මහලු ජසයාගේ තරුණ හා කපටි භාර්යාව", "මහ සම්මත රජුගේ මව", "වැදි රජුගේ සොහොයුරිය", "ගුරුහාමිගේ ගෝලයා", "ජසයා හා ලෙන්චිනා අතර සිදුවන ගැටුම් සමාජ හාස්‍යය මතු කරයි."),
        q("පහතරට කෝලම් නැටුමේ 'පරයා' නමැති චරිතය ඉදිරිපත් කරන ප්‍රධාන කාර්යය කුමක්ද?", "රෙදි ඇතිරීම හා හාස්‍යජනක විහිළු සංවාද පැවැත්වීම", "බෙර වාදනය පමණක් කිරීම", "සන්නි යකුන් දැමීම", "දෙවොල් මඩු පහන් දැල්වීම", "නාට්‍ය පෙළගැස්ම අතරතුර ප්‍රේක්ෂකයන් පිනවන විකට චරිතයකි."),
        q("පහතරට වෙස්මුහුණු කලාවේ 'මුහුණු කැපීම' සිදු කරන පාරම්පරික ශිල්පීන් හඳුන්වන්නේ කුමන නමකින්ද?", "වෙස්මුහුණු කැටයම් ශිල්පීන් (ආචාරිවරුන්)", "යාග මඩු ගොක් කොළ සැරසිලි ශිල්පීන්", "පහතරට බෙර හම් සාදන වාද්‍ය ශිල්පීන්", "වෙස් ඇඳුම් පබළු මසන කලා ශිල්පීන්", "අම්බලන්ගොඩ ආශ්‍රිතව මෙම පරම්පරාගත මුහුණු කැපීමේ කලාකරුවෝ වෙසෙති."),
        q("පහතරට 'රක්ෂ' (රකුසු) වෙස්මුහුණු නිර්මාණය කිරීමේදී යොදාගන්නා ප්‍රධාන වර්ණ මොනවාද?", "රතු, කහ, කොළ, කළු සහ සුදු යන දීප්තිමත් වර්ණ", "තනි අළු පැහැය පමණි", "ලා දුඹුරු පැහැය පමණි", "වර්ණ කිසිවක් නොයොදයි", "දීප්තිමත් වර්ණ සංයෝජනය වෙස්මුහුණට ආකර්ෂණීය හා භයංකාර පෙනුමක් ලබා දෙයි."),
        q("පහතරට වෙස්මුහුණු වර්ණ ගැන්වීමෙන් පසු ආලේප කරන 'දොරණ තෙල්' මිශ්‍රණයෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "දිලිසෙන ඔපය ලැබීම සහ තෙතමනයෙන් හා කෘමීන්ගෙන් ආරක්ෂා වීම", "තීන්ත ඉක්මනින් සේදී යාම", "ලීය කළු පැහැ වී පුපුරා යාම", "වෙස්මුහුණේ බර දෙගුණ වීම", "ස්වාභාවික දොරණ ගසේ තෙල් හා හල් දුම්මල එක් කර මෙම ඔප දැමීම සිදු කරයි."),
        q("පහතරට 'තෙල්මේ' නැටුමේදී නැට්ටුවා 'උඩුකය' අලංකාර කර ගැනීමට පළඳිනු ලබන විශේෂ රෙදි ආභරණය කුමක්ද?", "පපුව හරහා බඳින රතු හෝ සුදු සළුව හා මාල පොටවල්", "උඩරට රිදී අවුල්හැරය", "සන්නි මුහුණ", "කඩිප්පු යුගලය", "පහතරට උඩුකය ඇඳුම ඉතා සරල එහෙත් තාලයට පැද්දෙන අලංකාර සැරසිලිවලින් යුක්තය."),
        q("පහතරට නර්තනයේදී 'තෙල්මේ නැටුම' නැටීමේදී දෙපා තබන මූලික ඉරියව්ව හඳුන්වන්නේ කුමන නමකින්ද?", "පහතරට පළල් මණ්ඩිය", "සමපාද සිටීම", "ඒකපාද සිටීම", "බැලේ ඇඟිලි තුඩු සිටීම", "ශරීරයේ බර සමබරව පවත්වා ගනිමින් දෙපසට විහිදුණු මණ්ඩි ඉරියව්ව මෙහි මූලික වේ."),
        q("පහතරට නැටුමේ 'වට්ටම්' නැටීමේදී අවසානයේ යෙදෙන වේගවත් 'හමාර තීර්මානය' මඟින් සිදු වන්නේ කුමක්ද?", "නැටුමේ රිද්මයානුකූල නිමාව හා සම මත නතර වීම", "නැටුමේ ආරම්භය", "ප්‍රේක්ෂකයන්ගේ පැමිණීම", "වෙස්මුහුණ මාරු කිරීම", "සෑම වට්ටම් පෙළක්ම නිශ්චිත තීර්මානයකින් අවසන් කිරීම ශාස්ත්‍රීය රීතියයි."),
        q("පහතරට 'යක් බෙරය' වාදනය කිරීමේදී දෑත්වල ඇඟිලි හසුරුවන ආකාරය උඩරට ගැටබෙරයෙන් වෙනස් වන්නේ කෙසේද?", "දෙඅතේම ඇඟිලි හා අත්ලෙන් ගව සම් මත ශක්තිමත් සමතුලිත පහර එල්ල කිරීමෙන්", "දකුණු අතේ ඝන කඩිප්පුවක් හා වම් අතින් පමණක් ගැසීමෙන්", "දෙපයේ වළලුකරෙන් හා දණහිසෙන් බෙර ඇසට පහර දීමෙන්", "තම්මැට්ටම් කඩිප්පු දෙකක් භාවිත කර දෙපසට ගැසීමෙන්", "යක් බෙරයේ දෙපසම ගව සම් හෝ තලගොයි සම් නිසා ගැඹුරු හා තියුණු නාද උපදී."),
        q("පහතරට 'දහඅට සන්නියේ' සියලු සන්නි යකුන් වේදිකාවට පැමිණීමට පෙර 'අට පාලිය' ඉදිරිපත් කරන්නේ ඇයි?", "යාග මඩුව හා ආතුරයා පිරිසිදු කර රැකීමට", "යාග මඩුවේ දැල්වූ පන්දම් සියල්ල නිවීමට", "කෝලම් රජු හා බිසව වේදිකාවට කැඳවීමට", "සන්නි යාගයේ අවසන් ආශිර්වාදය පැවසීමට", "පන්දම්, සළු, කෙණ්ඩි හා කළස් ආදී පාලි නැටුම් පූර්ව ශුද්ධ කිරීමේ අංග වේ."),
        q("පහතරට 'කෝලම්' කතා පෙළේ 'රජ කෝලම' හා 'බිසව කෝලම' පැමිණෙන අවස්ථාවේදී ඔවුන් පැළඳ සිටින මුහුණුවල විශේෂත්වය කුමක්ද?", "උස් වූ රාජකීය ඔටුනු, රන්වන් වර්ණය හා ශාන්ත ගාම්භීර පෙනුම", "දත් නෙරා ගිය බියකරු මුහුණු", "නාග පෙන රාශියක්", "වඳුරු මුහුණු", "රාජකීයත්වය පෙන්වන සුන්දර හා ගාම්භීර වෙස්මුහුණු මේ සඳහා කපා ඇත."),
        q("පහතරට 'පහතරට පා සරඹ' පුහුණු වන ආධුනිකයා 'තකුඳ තකුඳ' වෙනුවට යොදා ගන්නා පහතරට සරඹ පද මොනවාද?", "දොං ජිං තක තරි කිට තක දොං", "ස රි ග ම ප ධ නි", "තෙයි තත් තා තෙයි", "තන තම් දන තනා", "යක් බෙරයේ අක්ෂර උච්චාරණය මත පහතරට සරඹ මාලාව ගොඩනැගී ඇත."),
        q("පහතරට 'සූනියම් කැපිල්ල' යාගයේදී ආතුරයා වාඩි වී සිටින 'වීදිය' සරසන විශේෂ ශාක කොටස කුමක්ද?", "ගොක් කොළ, පුවක් මල් හා කෙසෙල් බඩ", "ප්ලාස්ටික් මල් වැල්", "යකඩ කම්බි", "රෙදි කඩදාසි", "ස්වාභාවික ශාක ද්‍රව්‍යවලින් යාග මණ්ඩපය පවිත්‍රව සැකසීම පහතරට සම්ප්‍රදායයි."),
        q("පහතරට 'රට යකුම' හෙවත් 'රිද්දි යාගය' පවත්වන විට කළු යකාට පසුව පැමිණෙන කාන්තා චරිත හත කවුද?", "රිද්දි බිසවුන් හත්දෙනා", "සන්නි යකුන් දහඅට දෙනා", "වැදි රජුගේ සෙබළුන්", "හේවා රාළලා", "මුතු කුඩ, සේසත් හා කපු කැටීමේ නාටකීය ජවනිකා රිද්දි බිසවුන් ඉදිරිපත් කරයි."),
        q("පහතරට නර්තන කලාවේදී 'නාග රක්ෂ' නැටුමෙන් ප්‍රකාශ වන ප්‍රධාන පණිවිඩය හෝ සංකේතය කුමක්ද?", "සතුරු උවදුරු දුරු කර ආරක්ෂාව පැතීම", "ගොවි බිම් හා වනාන්තර හෙළි පෙහෙළි කිරීම", "මුහුදු යාත්‍රා හා පාරු ගමන් තහනම් කිරීම", "අමනුෂ්‍ය රෝග හා වසංගත බිය පැතිරවීම", "නාගයා ආරක්ෂක සංකේතයක් ලෙස ලාංකේය ජනශ්‍රැතියේ සැලකේ."),
        q("පහතරට 'ගුරුළු රක්ෂ' නැටුමේදී ගුරුළාගේ පියාපත් චලන නිරූපණය සඳහා නැට්ටුවා භාවිත කරන ශිල්පීය උපක්‍රමය කුමක්ද?", "දෑත් උරහිස් මට්ටමින් විහිදා වේගයෙන් කැරකෙමින් පැනීම", "බිම දිගා වී නිශ්චලව සිටීම", "අත් දෙක ඉණේ තබා ගැනීම", "දණහිස් බිම තැබීම", "ගුරුළාගේ අභීත පියාසර රටාව මෙම කැරකිලිවලින් මැනවින් පෙන්වයි."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'මාර රක්ෂ' හා 'සිංහ රක්ෂ' මුහුණු අයත් වන්නේ කුමන ප්‍රභේදයටද?", "රක්ෂ හෙවත් රකුසු වෙස්මුහුණු ගණයට", "සන්නි යක් මුහුණු ගණයට", "කෝලම් මිනිස් චරිත ගණයට", "උඩරට වෙස් තට්ටු ගණයට", "රකුසු මුහුණු බොහෝ විට අලංකාරය හා ආරක්ෂාව සංකේතවත් කරයි."),
        q("පහතරට 'කෝලම්' නැටුමේදී මුහුණු පැළඳ සිටින ශිල්පියාට සියුම් මුහුණු හැඟීම් පෙන්විය නොහැකි නිසා භාවය ප්‍රකාශ කරන්නේ කෙසේද?", "හිස ඇල කිරීම, ශරීර ඉරියව්, අත් චලන සහ කවි ගායනය මගින්", "වෙස්මුහුණ ගලවා බිම තැබීමෙන්", "මයික්‍රෆෝනයකින් කෑගැසීමෙන්", "පුවරුවක ලියා පෙන්වීමෙන්", "ශරීර භාෂාව හා රිද්මය මගින් වෙස්මුහුණට පවා ජීවය ලබා දීම නැට්ටුවාගේ දක්ෂතාවයි."),
        q("පහතරට 'දෙවොල් මඩුව' පැවැත්වීමේදී පත්තිනි දේවියගේ හා දෙවොල් දෙවියන්ගේ කතා පුවත් ගායනා කරන්නේ කුමන ආකාරයකින්ද?", "යාතිකා හා කෝල්මුර කවි ගායනා ලෙස", "බටහිර ඔපෙරා ගීත ලෙස", "කෙටි ගද්‍ය නිවේදන ලෙස", "ඉංග්‍රීසි පද්‍ය ලෙස", "දේව පුරාවෘත්ත රසවත් පද්‍ය හා ගායන තාලවලින් මඩුවේදී ඉදිරිපත් කෙරේ."),
        q("පහතරට 'මාතර ගුරුකුලයේ' නැටුම් පුහුණුවේදී වැඩි අවධානයක් යොමු කෙරෙන අංගයක් කුමක්ද?", "දිගු යක් බෙර වට්ටම් හා සම්පූර්ණ පාලි නැටුම්", "උඩරට දහඅට වන්නම් හා කස්තිරම් අඩව් පමණක්", "භාරතීය කථක් චක්කර් කැරකිලි පුහුණුව පමණක්", "සබරගමු දිගු දවුල හා ගමන් තාල පද පමණක්", "මාතර සම්ප්‍රදාය පහතරට පැරණිම හා පොහොසත්ම රිද්ම සම්ප්‍රදායක් ලෙස සැලකේ."),
        q("පහතරට 'බෙන්තර ගුරුකුලයේ' නර්තන ශෛලිය හඳුනා ගැනීමේදී කැපී පෙනෙන ලක්ෂණය කුමක්ද?", "මුහුණු හා රංගනයේ ඇති සියුම් නාටකීය බව හා රයිගම්/මාතර ලක්ෂණ සුසංයෝගය", "බෙර වාදනය හා තාලම්පට සම්පූර්ණයෙන්ම ඉවත් කර නැටීම", "කෝලම් හා සන්නි අංගවලදී වෙස්මුහුණු කිසිසේත් භාවිත නොකිරීම", "පාරම්පරික කාන්තා නැට්ටුවන්ට පමණක් සීමා වූ ලැසි ශෛලියක් වීම", "දකුණු හා බස්නාහිර සීමාවේ පිහිටි නිසා බෙන්තර සම්ප්‍රදාය අතිශය විචිත්‍රය."),
        q("පහතරට 'රයිගම් ගුරුකුලයේ' නර්තන අංග තුළ දක්නට ලැබෙන විශේෂිත භූගෝලීය බලපෑම කුමක්ද?", "බස්නාහිර හා සබරගමු සීමාවන්ට ආසන්න නිසා ලැබුණු මෘදු නැමෙනසුළු චලන ලක්ෂණ", "උතුරු ඉන්දියානු කථක් සම්ප්‍රදායේ වේගවත් චක්කර් කැරකීම් බලපෑම", "සාම්ප්‍රදායික ජපන් නෝ සහ කබුකි රංග කලා බලපෑම", "රුසියානු සම්භාව්‍ය බැලේ සපත්තු මත සිටගෙන නටන බලපෑම", "කළුතර අවට රයිගම කෝරළයේ නැටුම් ශෛලියට ප්‍රාදේශීය අනන්‍යතාවක් ඇත."),
        q("පහතරට වෙස්මුහුණු කලාවේදී 'නාග රක්ෂ' මුහුණේ නාග පෙන කැපීම සිදු කරන්නේ කෙසේද?", "වෙනම කැටයම් කර මුහුණේ දෙපසට හා හිස මුදුනට සවි කිරීමෙන්", "ප්ලාස්ටික්වලින් අලවා ගැනීමෙන්", "කඩදාසිවලින් ඇඳීමෙන්", "වර්ණවත් රෙදි එල්ලීමෙන්", "වෙන් කළ හැකි කොටස් ලෙස නාග පෙන හා කන් කැටයම් කර සවි කිරීම සිරිතයි."),
        q("පහතරට නර්තනයේ 'කළස් පාලිය' ඉදිරිපත් කරන නැට්ටුවා කළය හසුරුවන අයුරින් නිරූපණය කරන්නේ කුමක්ද?", "සමතුලිතතාව, සෞභාග්‍යය හා පිරිසිදු පූජාව", "කළය බිඳ දැමීම", "ජලය ඉවතට විසි කිරීම", "නැටුමෙන් විඩාවට පත්වීම", "පුන් කළස අතින් කරකවමින් හා හිස මත තබමින් අලංකාරව රඟ දක්වයි."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'අවමංගල්‍ය හෝ දුක්බර අවස්ථා' සඳහා යොදා නොගෙන උත්සවශ්‍රීයෙන් යෙදෙන නැටුම කුමක්ද?", "තෙල්මේ නැටුම", "මළ බෙර වාදනය", "හේවිසි ශෝක පදය", "කළු සළු හැඳීම", "තෙල්මේ යනු දෙවියන් පුදන ශුභදායක හා ප්‍රීතිමත් සමූහ නර්තනයකි."),
        q("පහතරට 'මඩු පෙළපාලියේ' දී 'පිදේනි' තැබීම සඳහා සාදන 'තටුව' තනා ගන්නේ කුමන ශාක කොටසින්ද?", "කෙසෙල් පතුරු සහ උණ බට පතුරු", "යකඩ තහඩු", "ප්ලාස්ටික් පෙට්ටි", "වීදුරු තැටි", "ස්වාභාවික කෙසෙල් පතුරු වලින් සතරැස් හෝ ත්‍රිකෝණාකාර පිදේනි තටු සාදයි."),
        q("පහතරට 'කෝලම්' රංගනයේදී 'ගැමි කාන්තාවන්' නිරූපණය කරන කෝලම් චරිතයකට උදාහරණයක් කුමක්ද?", "නොංචි අක්කා සහ ලෙන්චිනා", "ගජගා සහ තුරඟා", "සන්නි යකා සහ කළු යකා", "වඩිග බමුණා", "සාමාන්‍ය ජන ජීවිතයේ විවිධ කාන්තා චරිත කෝලම් නාට්‍යයේ ජීවමාන වේ."),
        q("පහතරට නර්තන සම්ප්‍රදායේ 'වෙස්මුහුණු කැපීමේ ශිල්පය' කුඩා කල සිට පරම්පරාගතව ඉගෙන ගැනීමෙන් රැකුණු කලා අංගය කුමක්ද?", "සාම්ප්‍රදායික කැටයම් මිනුම් හා ස්වාභාවික වර්ණ කලාව", "රන් රිදී පබළු වෙස් තට්ටු නෙළීමේ තාක්ෂණය", "සිංහල රබන් හා කළගෙඩි තැනීමේ ජන ශිල්පය", "රංග වස්ත්‍ර හා උඩරට හඟල මැසීමේ ශිල්පය", "අම්බලන්ගොඩ කලාකරුවෝ පරම්පරා ගණනාවක් තිස්සේ මෙම දුර්ලභ කලාව රැකගෙන එති."),
        q("පහතරට 'පාලි' අංග අතර 'දැල්වෙන පන්දම් දෙකක්' අතින් ගෙන නැට්ටුවා කරන විස්මයජනක දස්කම කුමක්ද?", "දුම්මල ගසා මහා ගිනි දැල් මවමින් දෑත් හා ශරීරය අතරින් පන්දම් කරකැවීම", "දැල්වෙන පන්දම් දෙක ජල කළයක් තුළ ඔබා එසැණින් නිවා දැමීම", "රඟ මඩලේ සිටින ප්‍රේක්ෂකයන් අතරට දැල්වූ පන්දම් විසි කිරීම", "යාග මඩුව මැද පන්දම් බිම දමා පයින් පාගා විනාශ කර දැමීම", "රාත්‍රී ශාන්තිකර්ම මඩුවේ අඳුර නසන අතිශය ත්‍රාසජනක දර්ශනයකි."),
        q("පහතරට 'දහඅට සන්නිය' වැනි ශාන්තිකර්ම සඳහා භාවිත කළ 'යක් බෙරය' වෙනුවෙන් හඳුන්වන තවත් ප්‍රකට නාමයක් කුමක්ද?", "දෙවොල් බෙරය හෙවත් ඝෝෂක බෙරය", "උඩරට උඩැක්කි වාද්‍ය භාණ්ඩය", "මධ්‍යම කඳුකර ගැටබෙරය", "දකුණු ඉන්දීය මෘදංග බෙරය", "පහතරට ප්‍රදේශයේ පූජා හා යාතුකර්මවලදී මෙම නාමයන් බහුලව යෙදේ."),
        q("පහතරට කෝලම් කලාවේ 'මුහුණු' නිර්මාණයේදී චරිතයේ වයස හා ගුණාංග පෙන්වීමට කලාකරුවා යොදන උපක්‍රමය කුමක්ද?", "මුහුණේ රැළි, දත් අඩු වීම, වර්ණය හා නළලේ හැඩතල වෙනස් කිරීම", "සියලු මුහුණු එකම ආකාරයෙන් තැබීම", "මුහුණේ නම ලිවීම පමණක්", "කඩදාසි ඇලවීම", "නොංචි අක්කාගේ දත් හැළුණු මුහුණ හා රැළි වැටුණු කම්මුල් ඊට කදිම නිදසුනකි."),
        q("පහතරට නැටුමේදී 'තෙල්මේ' නැට්ටුවා පාදයේ සිළම්බු පැළඳීමට පෙර ගුරුවරයාට වඳින්නේ ඇයි?", "ශිල්පයට හා කලා භාණ්ඩවලට ගෞරව දැක්වීමට", "සිළම්බු පටිය ලිහිල් වී ගැලවී යාම නිසා", "වේදිකාවට පිවිසීමේ බිය නැති කර ගැනීමට", "තෙල්මේ පද ආරම්භ කිරීම පමා කර ගැනීමට", "සියලු දේශීය නර්තන අංග ගුරු ගෞරවය හා විනය මත පදනම් වේ."),
        q("පහතරට 'ගම්මඩු' සහ 'දෙවොල් මඩු' නැටුම්වලදී කාන්තා නියෝජනයට වඩා පිරිමි නැට්ටුවන් වැඩි වශයෙන් සහභාගී වූයේ ඇයි?", "එළිවෙන තුරු රාත්‍රී කාලයේ ගිනි පෑගීම වැනි දුෂ්කර යාග කටයුතු පැවති බැවින්", "කාන්තාවන්ට දේශීය බෙර තාල හා සංගීතය කිසිසේත් නොතේරෙන නිසා", "රංගනය සඳහා සුදුසු සාම්ප්‍රදායික රංග වස්ත්‍ර හා සළු නොතිබූ නිසා", "ගම්මඩු රඟ මඩලේ ඉඩකඩ ඉතා කුඩා ප්‍රමාණයකට සීමා වී තිබූ නිසා", "කෙසේ වෙතත් වර්තමානයේ පාසල් හා වේදිකා රංගනයේදී දෙපාර්ශ්වයම සමව හදාරති."),
        q("පහතරට 'රකුසු' වෙස්මුහුණු කැපීමේදී ඒවායේ ඇස් නෙරා ගිය ආකාරයෙන් සකසන්නේ කුමක් සංකේතවත් කිරීමටද?", "දුෂ්ට බලවේග පලවා හරින තියුණු බැල්ම හා අධිමානුෂික බලය", "අන්ධභාවය", "නිදිමත ගතිය", "සාමාන්‍ය දුර්වල බව", "රක්ෂ මුහුණුවල නෙරා ගිය දෑස් ආරක්ෂක තේජස ප්‍රකාශ කරයි."),
        q("පහතරට නැටුමේදී 'වෙස්මුහුණ' පැළඳ ගැනීමෙන් පසු නැට්ටුවාගේ ප්‍රධාන වගකීම කුමක්ද?", "සම්පූර්ණ රංගනය තුළ අදාළ වෙස්මුහුණේ චරිතය ජීවමාන කිරීම", "තමන්ගේ සාමාන්‍ය පෞද්ගලික හැසිරීම පෙන්වීම", "වෙස්මුහුණ ඉක්මනින් ගලවා දැමීම", "බෙර වාදකයාට බාධා කිරීම", "මුහුණ පැළඳගත් මොහොතේ සිට නළුවා එම චරිතය බවට පත් වේ."),
        q("පහතරට නර්තන කලාවට 'පාසල් විෂය නිර්දේශය' තුළ වැදගත් ස්ථානයක් හිමි වී ඇත්තේ ඇයි?", "දේශීය යාතුකර්ම, කැටයම් හා ජන නාට්‍ය රැකීමට", "ප්‍රායෝගික පුහුණුවක් අවශ්‍ය නොවන නිසා", "ලිඛිත පරීක්ෂණ කිසිවක් නොමැති නිසා", "විදේශීය සම්භාව්‍ය නැටුම් ඉගෙන ගැනීමට", "ශ්‍රී ලාංකේය සංස්කෘතික විවිධත්වය අගය කරන දරු පරපුරක් බිහි කිරීම අරමුණයි."),
        q("පහතරට 'කෝලම් හා සන්නි' නැටුම් කලා ලෝකය පුරා ප්‍රකට වීමට හේතු වූ ප්‍රධාන සාධකය කුමක්ද?", "වෙස්මුහුණු කැටයම් කලාව හා නාට්‍ය රංගනය", "විදේශීය චිත්‍රපට පිටපත් වීම", "බටහිර සංගීත තැටි නිපදවීම", "පැරණි ගොවි ආයුධ නිෂ්පාදනය", "සිංහල වෙස්මුහුණු කලාව ලෝක කලා කෞතුකාගාරවල පවා අගය කෙරෙන මහඟු උරුමයකි.")
    )
}
